import com.google.gson.*;
import dev.hua.ptcglive.ai.*;
import dev.hua.ptcglive.engine.*;
import dev.hua.ptcglive.engine.effect.*;
import dev.hua.ptcglive.engine.field.*;
import dev.hua.ptcglive.rules.*;
import java.util.*;

public final class NonPokemonBatch123Test {
    static final UUID A=DynamicPassiveModifierTest.A,B=DynamicPassiveModifierTest.B;
    static final String ID="swsh1_en_186";
    static void check(boolean b,String why){if(!b)throw new AssertionError(why);}
    static void reject(Runnable r){GeneratedRuleBatch8Test.reject(r);}
    static UUID other(UUID p){return p.equals(A)?B:A;}
    static UUID active(ServerMatch m,UUID p){return m.activePokemonView(p).pokemonId();}
    static UUID bench(ServerMatch m,UUID p){return m.benchPokemonView(p).getFirst().pokemonId();}
    static CardInstance hand(ServerMatch m,UUID p,String key){return DynamicPassiveModifierTest.hand(m,p,key);}
    static EnergyProfile aurora(){return NonPokemonBatch2Test.DATA.energyProfile(ID).orElseThrow();}
    static TrainerProfile trainer(String id){return NonPokemonBatch2Test.DATA.trainer(id).orElseThrow();}
    static ServerMatch game(){return game(DynamicPassiveModifierTest.plainStadium(),trainer("sm8_en_173"));}
    static ServerMatch game(TrainerProfile stadium,TrainerProfile item){return DynamicPassiveModifierTest.fixture(DynamicPassiveModifierTest.plainTool(),stadium,aurora(),GeneratedRuleBatch8Test.hit(100,false),List.of(),0,item);}
    static void settle(ServerMatch m){NonPokemonBatch103Test.settle(m);}
    static void pay(ServerMatch m,UUID p,List<CardInstance> cards){var q=m.effectCardPrompt(p);m.submitEffectCards(p,q.resolutionId(),q.step(),cards.stream().map(CardInstance::instanceId).toList());}
    static void keep(ServerMatch m,UUID p,List<CardInstance> cards){var discard=m.privateView(p).hand().stream().filter(c->!cards.contains(c)).map(CardInstance::instanceId).toList();m.discardHandCardsByEffect(m.currentPlayer(),p,discard);}
    public static void main(String[] args){manual();authority();insufficient();effectSources();multiple();programs();suppressionAndTraps();stale();ai();schema();System.out.println("NonPokemonBatch123Test passed: Aurora manual/effect hand cost, private authority and atomic payment, exactly one rainbow unit, Deck/Discard/move exclusions, multi-card and distributed attachments, resumed suffix and trigger order, suppression and hand locks, stale plans and four AI difficulties");}
    static void manual(){for(UUID p:List.of(A,B))for(boolean benched:List.of(false,true)){
        var m=game();if(p.equals(B))m.endTurn(A);UUID host=benched?bench(m,p):active(m,p);var energy=hand(m,p,"special");var cost=hand(m,p,"energy");int size=m.privateView(p).hand().size();m.attachEnergy(p,energy.instanceId(),host);
        check(!m.energyAttached(p)&&m.privateView(p).hand().contains(energy)&&!EventTargetBindingTest.field(m).attachedEnergy(p,host).contains(energy),"Aurora attached or consumed quota before cost");var q=m.effectCardPrompt(p);check(q.minimum()==1&&q.maximum()==1&&!q.candidates().contains(energy),"Aurora may discard itself");pay(m,p,List.of(cost));
        check(m.energyAttached(p)&&m.privateView(p).hand().size()==size-2&&m.privateView(p).discard().contains(cost)&&EventTargetBindingTest.field(m).attachedEnergy(p,host).contains(energy),"Manual payment/attachment/quota incorrect");
        var units=m.decisionEnergy(p).get(host).units();check(units.size()==1&&units.getFirst().selectableTypes().containsAll(EnumSet.allOf(EnergyType.class)),"Aurora lost one-unit any-type provision");check(!EnergyProfile.canPay(List.of(aurora()),Map.of(EnergyType.GRASS,1,EnergyType.FIRE,1)),"One Aurora paid two different requirements");reject(()->m.attachEnergy(p,hand(m,p,"energy").instanceId(),host));
    }}
    static void authority(){var m=game();var energy=hand(m,A,"special");m.attachEnergy(A,energy.instanceId(),active(m,A));var q=m.effectCardPrompt(A);String hidden=new Gson().toJson(m.clientView(B));for(var c:q.candidates())check(!hidden.contains(c.instanceId().toString()),"Opponent saw cost candidates");reject(()->m.effectCardPrompt(B));reject(()->m.submitEffectCards(B,q.resolutionId(),q.step(),List.of(q.candidates().getFirst().instanceId())));reject(()->pay(m,A,List.of(energy)));reject(()->pay(m,A,List.of()));reject(()->pay(m,A,List.of(hand(m,B,"energy"))));reject(()->m.endTurn(A));var selected=q.candidates().getFirst();pay(m,A,List.of(selected));reject(()->m.submitEffectCards(A,q.resolutionId(),q.step(),List.of(selected.instanceId())));}
    static void insufficient(){for(boolean effect:List.of(false,true)){var m=game();var energy=hand(m,A,"special");keep(m,A,List.of(energy));var before=m.clientView(A);check(!m.canAttachEnergy(A,energy.instanceId(),active(m,A)),"Only Aurora in hand counted itself as cost");if(effect)reject(()->m.attachEnergyByEffect(A,A,EffectSourceZone.HAND,energy.instanceId(),A,active(m,A)));else reject(()->m.attachEnergy(A,energy.instanceId(),active(m,A)));check(m.clientView(A).equals(before)&&!m.hasPendingEffectChoice()&&!m.energyAttached(A),"Unaffordable attempt changed state");}}
    static void effectSources(){for(UUID p:List.of(A,B))for(var zone:EffectSourceZone.values()){
        var m=game();if(p.equals(B))m.endTurn(A);var energy=hand(m,p,"special");if(zone!=EffectSourceZone.HAND){PairedTrainerPlayTest.zone(m,p,"hand").remove(energy);PairedTrainerPlayTest.zone(m,p,zone==EffectSourceZone.DECK?"deck":"discard").add(energy);keep(m,p,List.of());}
        int hand=m.privateView(p).hand().size();m.attachEnergyByEffect(p,p,zone,energy.instanceId(),p,active(m,p));if(zone==EffectSourceZone.HAND){check(m.hasPendingCardSelection(),"Hand effect bypassed Aurora cost");pay(m,p,List.of(NonPokemonBatch123Test.hand(m,p,"energy")));}else check(!m.hasPendingEffectChoice()&&m.privateView(p).hand().size()==hand,"Off-hand attachment charged cost");
        check(!m.energyAttached(p)&&EventTargetBindingTest.field(m).attachedEnergy(p,active(m,p)).contains(energy),"Effect attachment incorrectly spent manual quota");m.moveAttachedEnergyByEffect(p,p,active(m,p),p,bench(m,p),List.of(energy.instanceId()));check(!m.hasPendingEffectChoice(),"Moving already attached Aurora charged cost");
    }}
    static void multiple(){for(boolean enough:List.of(false,true)){var m=game();var energies=m.privateView(A).hand().stream().filter(c->c.definitionId().equals("special")).limit(2).toList();check(energies.size()==2,"Two Aurora fixture");var costs=m.privateView(A).hand().stream().filter(c->c.definitionId().equals("energy")).limit(enough?2:1).toList();var held=new ArrayList<>(energies);held.addAll(costs);keep(m,A,held);var policy=new ServerMatch.EnergyAttachmentPolicy(2,2,ServerMatch.InPlayTargetScope.OWN_FIELD,false,Set.of());var ids=energies.stream().map(CardInstance::instanceId).toList();
        if(!enough){var before=m.clientView(A);reject(()->m.attachEnergyByEffect(A,policy,A,EffectSourceZone.HAND,ids,A,active(m,A)));check(m.clientView(A).equals(before),"Unaffordable multi-attach partially moved cards");continue;}
        m.attachEnergyByEffect(A,policy,A,EffectSourceZone.HAND,ids,A,active(m,A));check(m.effectCardPrompt(A).minimum()==2&&m.effectCardPrompt(A).candidates().equals(costs),"Two Aurora shared one cost or allowed selected energy as payment");reject(()->pay(m,A,List.of(costs.getFirst(),costs.getFirst())));pay(m,A,costs);check(EventTargetBindingTest.field(m).attachedEnergy(A,active(m,A)).containsAll(energies)&&m.privateView(A).hand().isEmpty(),"Two Aurora did not pay two separate cards");
    }}
    static TrainerProfile attachment(boolean distributed){String json="{\"trainerCategory\":\"ITEM\",\"effects\":[{\"type\":\"attach_energy\",\"target\":\"SELECT_OWN_POKEMON\",\"source\":\"HAND\",\"amount\":2,\"minimum\":2,\"special_energy_only\":true,\"target_scope\":\"OWN_FIELD\",\"distribution\":\""+(distributed?"ANY":"SAME_TARGET")+"\",\"bind\":\"attached\"},{\"type\":\"draw\",\"target\":\"SELF\",\"amount\":1,\"count_bind\":\"attached\"}]}";return BundledCombatData.trainer(JsonParser.parseString(json).getAsJsonObject(),EffectRegistry.standard());}
    static void programs(){for(boolean distributed:List.of(false,true)){
        var m=game(DynamicPassiveModifierTest.plainStadium(),attachment(distributed));var energies=m.privateView(A).hand().stream().filter(c->c.definitionId().equals("special")).limit(2).toList();var costs=m.privateView(A).hand().stream().filter(c->c.definitionId().equals("energy")).limit(2).toList();m.playTrainer(A,hand(m,A,"item").instanceId(),null);var q=m.effectCardPrompt(A);m.submitEffectCards(A,q.resolutionId(),q.step(),energies.stream().map(CardInstance::instanceId).toList());
        var target=m.effectAttachmentPrompt(A);if(distributed){for(int i=0;i<energies.size();i++)m.assignEffectEnergyDistribution(A,target.resolutionId(),target.step(),energies.get(i).instanceId(),i==0?active(m,A):bench(m,A));m.confirmEffectEnergyDistribution(A,target.resolutionId(),target.step());}else m.chooseEffectAttachmentTarget(A,target.resolutionId(),target.step(),active(m,A));
        int deck=m.privateView(A).deck().size(),held=m.privateView(A).hand().size();check(m.hasPendingCardSelection()&&m.effectCardPrompt(A).minimum()==2,"Effect did not pause for cost");pay(m,A,costs);settle(m);check(!m.hasPendingEffectChoice()&&m.privateView(A).deck().size()==deck-2&&m.privateView(A).hand().size()==held-2,"Attachment bind/draw suffix ran early or lost actual attached count");check(!m.energyAttached(A),"Resumed effect spent manual quota");
    }}
    static void suppressionAndTraps(){for(String stadium:List.of("swsh10_en_155","bw9_en_100")){var m=game(trainer(stadium),trainer("sm8_en_173"));m.playTrainer(A,hand(m,A,"stadium").instanceId(),null);var energy=hand(m,A,"special");int damage=m.activePokemonView(A).damage();m.attachEnergy(A,energy.instanceId(),active(m,A));check(m.activePokemonView(A).damage()==damage,"Frozen City ran before cost");pay(m,A,List.of(hand(m,A,"energy")));settle(m);if(stadium.equals("bw9_en_100"))check(m.activePokemonView(A).damage()==damage+20,"Frozen City missed completed hand attachment");else check(m.decisionEnergy(A).get(active(m,A)).units().getFirst().selectableTypes().equals(Set.of(EnergyType.COLORLESS)),"Temple failed to suppress provision after charging printed cost");}
        var m=game();var energy=hand(m,A,"special");var cost=hand(m,A,"energy");EventTargetBindingTest.field(m).preventHandEnergy(B,A,active(m,A));check(!m.canAttachEnergy(A,energy.instanceId(),active(m,A)),"Manual hand lock ignored");m.attachEnergyByEffect(A,A,EffectSourceZone.HAND,energy.instanceId(),A,active(m,A));check(!m.hasPendingEffectChoice()&&m.privateView(A).discard().contains(energy)&&m.privateView(A).hand().contains(cost),"Failed effect attachment charged cost or fired a selector");
    }
    static void stale(){for(boolean host:List.of(false,true)){var m=game();var energy=hand(m,A,"special");UUID target=bench(m,A);m.attachEnergy(A,energy.instanceId(),target);var q=m.effectCardPrompt(A);var cost=q.candidates().getFirst();if(host)EventTargetBindingTest.field(m).removePokemonByEffect(A,target);else PairedTrainerPlayTest.zone(m,A,"hand").remove(cost);var before=List.copyOf(m.privateView(A).discard());reject(()->m.submitEffectCards(A,q.resolutionId(),q.step(),List.of(cost.instanceId())));check(m.privateView(A).discard().equals(before)&&!m.energyAttached(A),"Stale Aurora payment discarded cards or consumed quota");m.concede(A);check(m.phase()==MatchPhase.FINISHED&&!m.hasPendingEffectChoice(),"Concede retained pending cost");}}
    static void ai(){for(var level:AiDifficulty.values())for(boolean effect:List.of(false,true)){var m=effect?game(DynamicPassiveModifierTest.plainStadium(),attachment(true)):game();var s=MatchSession.multiplayer(m,A,B);if(effect)m.playTrainer(A,hand(m,A,"item").instanceId(),null);else m.attachEnergy(A,hand(m,A,"special").instanceId(),active(m,A));AiCardOperationTest.settle(s,level);check(!m.hasPendingEffectChoice(),"AI failed Aurora cost "+level);AiCardOperationTest.finish(s,level);check(m.phase()==MatchPhase.FINISHED,"AI stalled Aurora match "+level);}}
    static void schema(){check(aurora().handDiscardCost()==1,"Missing actual Aurora printed cost");for(String value:List.of("0","2","true","\"1\"","1.5")){var j=JsonParser.parseString("{\"energyUnits\":[[\"COLORLESS\"]],\"handDiscardCost\":"+value+"}").getAsJsonObject();reject(()->BundledCombatData.specialEnergy(j,EffectRegistry.standard()));}}
}
